using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Minimal API")]
    [TestClass]
    public class RJIT_CR_MAPI_00010 : MinimalApiTestBase
    {
        [TestMethod]
        public void Each_Minimal_Api_Mapping_Must_Use_WithDescription_For_Client_Generation()
        {
            var invalidEndpointMappings = (from mapStatement in MapStatements
                                           where mapStatement.SyntaxTree.DoesNotContain(".WithDescription")
                                           select new
                                           {
                                               Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FilePath:  {mapStatement.FilePath}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Syntax:    

{mapStatement.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{mapStatement.SyntaxTree.Replace("});", "}).WithDescription(\"This is an amazing endpoint. This will provide you all data you like to have :)\");").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                           }).ToImmutableList();

            Assert.IsTrue(invalidEndpointMappings.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MAPI_00010

Please provide a good undertandable description for each endpoint. This is important for customers or other teams
who want to use your API. Provide all usefull information, about why this endpoint, filters, how to use it, 
what to expect, not so obviuos things and so on.

Findings {invalidEndpointMappings.Count}': 

{invalidEndpointMappings.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
